# title: o6_5 – Förderbarkeit einzelner Tiere
# description: >-
#   Tierbezogene Voraussetzungen (Rassenliste, Reinrassigkeit, Tierkategorien,
#   Bestätigung der Zuchtorganisation, Beantragung). Ergebnis ist die Menge
#   base_failures mit Paaren [animal_id, rule_id].
package oepul.o6_5

# O6_5-ELIG-UNKNOWN-CATEGORY: nur die Tierkategorien der Maßnahme sind förderbar.
base_failures contains [a.animal_id, "O6_5-ELIG-UNKNOWN-CATEGORY"] if {
	some a in animals
	not category_meta[a.animal_category]
}

# O6_5-ELIG-BREED-LIST: reinrassige Tiere der Rassenliste (Anhang D / Kapitel 8).
base_failures contains [a.animal_id, "O6_5-ELIG-BREED-LIST"] if {
	some a in animals
	not breed_listed(a)
}

breed_listed(a) if {
	b := breed_meta[a.breed]
	b.species == species_of(a)
}

# O6_5-ELIG-PUREBRED-HERDBOOK: reinrassige Zuchttiere gemäß Tierzuchtgesetzen der
# Länder und genehmigten Zuchtprogrammen mit Zuchtziel Erhalt der Rasse.
base_failures contains [a.animal_id, "O6_5-ELIG-PUREBRED-HERDBOOK"] if {
	some a in animals
	not purebred_breeding_animal(a)
}

purebred_breeding_animal(a) if {
	a.is_purebred == true
	a.herdbook_registered == true
	a.approved_breeding_program == true
}

# O6_5-ELIG-REGULAR-BREEDING: regelmäßiger Zuchteinsatz im genehmigten Zuchtprogramm.
base_failures contains [a.animal_id, "O6_5-ELIG-REGULAR-BREEDING"] if {
	some a in animals
	not a.regular_breeding_use == true
}

# O6_5-ELIG-FEMALE-PUREBRED-MATING: weibliche Tiere nur reinrassige Anpaarung.
base_failures contains [a.animal_id, "O6_5-ELIG-FEMALE-PUREBRED-MATING"] if {
	some a in animals
	is_female(a)
	not a.purebred_mating_only == true
}

offspring_by_reference(a, field) if {
	d := val(a, field)
	d != null
	parse_date(d) <= requirement_ref_ns(a)
}

# O6_5-ELIG-FIRST-BIRTH-STICHTAG: Kuh gekalbt, Mutterschaf gelammt, Mutterziege
# gekitzt – jeweils bis spätestens am Stichtag 01.04.
base_failures contains [a.animal_id, "O6_5-ELIG-FIRST-BIRTH-STICHTAG"] if {
	some a in animals
	a.animal_category in {"kuh", "mutterschaf", "mutterziege"}
	not offspring_by_reference(a, "first_offspring_date")
}

# O6_5-ELIG-MARE-FOALING: Stute bis spätestens 31.05. einmal gefohlt.
base_failures contains [a.animal_id, "O6_5-ELIG-MARE-FOALING"] if {
	some a in animals
	a.animal_category == "stute"
	not offspring_by_reference(a, "first_offspring_date")
}

# O6_5-ELIG-MARE-REFOALING: weitere Abfohlung spätestens 3,5 Jahre nach der letzten.
base_failures contains [a.animal_id, "O6_5-ELIG-MARE-REFOALING"] if {
	some a in animals
	a.animal_category == "stute"
	not mare_refoaling_ok(a)
}

last_foaling_date(a) := val(a, "last_foaling_date") if {
	val(a, "last_foaling_date") != null
} else := val(a, "first_offspring_date")

mare_refoaling_ok(a) if {
	last := last_foaling_date(a)
	last != null
	requirement_ref_ns(a) <= time.add_date(parse_date(last), 0, params.mare_refoaling_max_months, 0)
}

# O6_5-ELIG-SOW-PUREBRED-FARROWING: Zuchtsau bis Stichtag zumindest einmal reinrassig geferkelt.
base_failures contains [a.animal_id, "O6_5-ELIG-SOW-PUREBRED-FARROWING"] if {
	some a in animals
	a.animal_category == "zuchtsau"
	not offspring_by_reference(a, "first_purebred_farrowing_date")
}

# O6_5-ELIG-SOW-LITTER-SHARE: mindestens jeder 2. Wurf reinrassig.
base_failures contains [a.animal_id, "O6_5-ELIG-SOW-LITTER-SHARE"] if {
	some a in animals
	a.animal_category == "zuchtsau"
	not sow_litter_share_ok(a)
}

sow_litter_share_ok(a) if {
	total := val(a, "litters_total")
	pure := val(a, "litters_purebred")
	is_number(total)
	is_number(pure)
	total >= 1
	pure <= total
	pure >= total * params.sow_min_purebred_litter_share
}

# O6_5-ELIG-MALE-ANNUAL-BREEDING: jährlicher Zuchteinsatz, ausgenommen im Jahr der Zulassung.
base_failures contains [a.animal_id, "O6_5-ELIG-MALE-ANNUAL-BREEDING"] if {
	some a in animals
	category_meta[a.animal_category].annual_breeding_use_required == true
	not annual_breeding_ok(a)
}

annual_breeding_ok(a) if a.breeding_use_in_year == true

annual_breeding_ok(a) if val(a, "breeding_approval_year") == year

# O6_5-ELIG-MALE-MIN-AGE / O6_5-ELIG-STALLION-MIN-AGE: Mindestalter am Bezugsdatum.
base_failures contains [a.animal_id, rule_id] if {
	some a in animals
	meta := category_meta[a.animal_category]
	meta.min_age_months != null
	rule_id := meta.min_age_rule_id
	not min_age_ok(a, meta.min_age_months)
}

min_age_ok(a, months) if {
	b := val(a, "birth_date")
	b != null
	time.add_date(parse_date(b), 0, months, 0) <= requirement_ref_ns(a)
}

# O6_5-ELIG-STALLION-OFFSPRING: Hengst am 31.05. älter als 5 Jahre -> lebend geborener
# Nachkomme in den letzten 2 Jahren im Zuchtbuch registriert.
base_failures contains [a.animal_id, "O6_5-ELIG-STALLION-OFFSPRING"] if {
	some a in animals
	a.animal_category == "zuchthengst"
	stallion_older_than_limit(a)
	not a.live_offspring_registered_last_2_years == true
}

stallion_older_than_limit(a) if {
	b := val(a, "birth_date")
	b != null
	time.add_date(parse_date(b), params.stallion_offspring_check_age_years, 0, 0) < requirement_ref_ns(a)
}

# O6_5-GEN-ANIMALS-IN-AUSTRIA: geförderte Tiere müssen in Österreich gehalten werden.
base_failures contains [a.animal_id, "O6_5-GEN-ANIMALS-IN-AUSTRIA"] if {
	some a in animals
	not a.kept_in_austria == true
}

# O6_5-OBL-BREEDING-ORG-CONFIRMATION: Bestätigung der Zuchtorganisation bis 10.02. des Folgejahres.
base_failures contains [a.animal_id, "O6_5-OBL-BREEDING-ORG-CONFIRMATION"] if {
	some a in animals
	not breeding_org_confirmed(a)
}

breeding_org_confirmed(a) if {
	c := a.breeding_org_confirmation
	c.status == "confirmed"
	not confirmation_late(c)
}

confirmation_late(c) if {
	val(c, "date") != null
	parse_date(c.date) > date_of(year + 1, params.breeding_org_confirmation_deadline_md)
}

# O6_5-APP-INDIVIDUAL-MFA: Pferde, Schafe, Ziegen, Schweine einzeln im Mehrfachantrag
# (Beilage "Gefährdete Nutztierrassen") mit Stichtag 01.04.; Rinder automatisch.
base_failures contains [a.animal_id, "O6_5-APP-INDIVIDUAL-MFA"] if {
	some a in animals
	category_meta[a.animal_category]
	not is_cattle(a)
	not is_replacement(a)
	not a.applied_in_mfa == true
}

# O6_5-OBL-HOLDING-PERIOD (Beginn): beantragte Tiere ab 01.04. am Betrieb.
base_failures contains [a.animal_id, "O6_5-OBL-HOLDING-PERIOD"] if {
	some a in animals
	not is_replacement(a)
	not on_farm_at_stichtag(a)
}

on_farm_at_stichtag(a) if {
	f := val(a, "on_farm_from")
	f != null
	parse_date(f) <= holding_start_ns
	not departed_before_holding_start(a)
}

departed_before_holding_start(a) if departure_date_ns(a) < holding_start_ns

# O6_5-OBL-TRANSFER-LIMITS: Weitergabe während der Haltedauer nur in den zulässigen Fällen.
base_failures contains [a.animal_id, "O6_5-OBL-TRANSFER-LIMITS"] if {
	some a in animals
	some t in object.get(a, "temporary_absences", [])
	not absence_permitted(a, t)
}

absence_days(t) := days_between_ns(parse_date(t.start_date), parse_date(t.end_date))

# O6_5-DEF-PASTURE-NOT-DEPARTURE
absence_permitted(_, t) if {
	t.type == "alpine_or_common_pasture"
	t.control_retained_or_care_only == true
}

# O6_5-OBL-TRANSFER-BREEDING-STATION-6M
absence_permitted(_, t) if {
	t.type == "breeding_station"
	val(t, "end_date") != null
	parse_date(t.end_date) <= time.add_date(parse_date(t.start_date), 0, params.breeding_station_max_months, 0)
}

# O6_5-OBL-TRANSFER-MALE-BREEDING-3M
absence_permitted(a, t) if {
	t.type == "male_breeding_use_other_farm"
	is_male(a)
	val(t, "end_date") != null
	parse_date(t.end_date) <= time.add_date(parse_date(t.start_date), 0, params.male_breeding_use_max_months, 0)
}

# O6_5-OBL-SHORT-ABSENCE-10-DAYS
absence_permitted(_, t) if short_documented_absence(t)

short_documented_absence(t) if {
	val(t, "end_date") != null
	absence_days(t) <= params.short_absence_max_days
	t.documented == true
}

# O6_5-PREM-RATES: für Kategorie/Prämienstufe muss ein Prämiensatz existieren.
base_failures contains [a.animal_id, "O6_5-PREM-RATES"] if {
	some a in animals
	breed_listed(a)
	not is_number(base_rate(a))
}

base_failed(id) if {
	some f in base_failures
	f[0] == id
}

base_ok(a) if not base_failed(a.animal_id)

# title: o6_5 – Förderwerbende Person, Beantragung, Vertrag und Ausstieg
# description: >-
#   Allgemeine Fördervoraussetzungen (förderwerbende Person, Betriebsmindestgröße,
#   Kontrollduldung) und maßnahmenbezogene Vertragsregeln (Antragsfrist, letzter
#   Einstieg, Wiedereinstieg, Abmeldung, Maßnahmenübernahme, Mindestteilnahme).
package oepul.o6_5

allowed_legal_forms := {f.legal_form | some f in data.o6_5.applicant_legal_forms}

# O6_5-GEN-APPLICANT-LEGAL-FORM
applicant_failures contains "O6_5-GEN-APPLICANT-LEGAL-FORM" if {
	not applicant.legal_form in allowed_legal_forms
}

# O6_5-GEN-PUBLIC-BODY-EXCLUDED: Gebietskörperschaften und Einrichtungen mit
# bestimmendem Einfluss (> 25 %) sind bei o6_5 nicht förderwerbend.
applicant_failures contains "O6_5-GEN-PUBLIC-BODY-EXCLUDED" if {
	applicant.is_public_body == true
	not public_body_exempt_measure("o6_5")
}

applicant_failures contains "O6_5-GEN-PUBLIC-BODY-EXCLUDED" if {
	applicant.public_body_share_percent > params.public_body_max_share_percent
	not public_body_exempt_measure("o6_5")
}

public_body_exempt_measure(m) if {
	some e in data.o6_5.public_body_exempt_measures
	e.measure == m
	e.from_year <= year
	exempt_until_ok(e)
}

exempt_until_ok(e) if e.to_year == null

exempt_until_ok(e) if year <= e.to_year

# O6_5-GEN-ACTIVE-FARMER
applicant_failures contains "O6_5-GEN-ACTIVE-FARMER" if {
	not applicant.is_active_farmer == true
}

applicant_failures contains "O6_5-GEN-ACTIVE-FARMER" if {
	not applicant.performs_agricultural_activity == true
}

# O6_5-GEN-MIN-FARM-SIZE: nur im ersten ÖPUL-Teilnahmejahr.
first_oepul_year := object.get(input, ["oepul_participation", "first_oepul_year"], null)

applicant_failures contains "O6_5-GEN-MIN-FARM-SIZE" if {
	first_oepul_year == year
	not min_farm_size_ok
}

min_farm_size_ok if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= params.min_protected_cultivation_area_first_year_ha
}

min_farm_size_ok if total_area_ha >= params.min_farm_area_first_year_ha

# O6_5-CTRL-REFUSAL: Verweigerung/Verhinderung der Vor-Ort-Kontrolle (außer höhere Gewalt).
applicant_failures contains "O6_5-CTRL-REFUSAL" if {
	object.get(input, ["documentation", "inspection_refused"], false) == true
	not object.get(input, ["documentation", "inspection_refusal_force_majeure"], false) == true
}

start_year := val(participation, "participation_start_year")

# O6_5-APP-DEADLINE: Maßnahmenantrag bis 31.12. vor Vertragsbeginn.
application_timely if {
	is_number(start_year)
	d := val(participation, "measure_application_date")
	d != null
	parse_date(d) <= date_of(start_year - 1, params.application_deadline_md)
}

contract_failures contains "O6_5-APP-DEADLINE" if not application_timely

# O6_5-APP-LAST-ENTRY: letzter Einstieg mit Förderjahr 2027.
contract_failures contains "O6_5-APP-LAST-ENTRY" if {
	is_number(start_year)
	start_year > params.last_entry_year
}

contract_failures contains "O6_5-CON-NOT-STARTED" if {
	is_number(start_year)
	start_year > year
}

# O6_5-CON-REENTRY-AFTER-LAPSE: nach Erlöschen neuer fristgerechter Maßnahmenantrag
# oder Korrektur zum vorhergehenden Maßnahmenantrag plus schriftliches Ersuchen.
contract_failures contains "O6_5-CON-REENTRY-AFTER-LAPSE" if {
	participation.previous_year_contract_lapsed == true
	not reentry_ok
}

reentry_ok if {
	d := val(participation, "reapplication_date")
	d != null
	parse_date(d) <= date_of(year - 1, params.application_deadline_md)
	year <= params.last_entry_year
}

reentry_ok if {
	participation.late_reentry_correction == true
	participation.written_request_submitted == true
	year <= params.last_entry_year
}

# O6_5-EXIT-DEREGISTRATION-TIMING: Abmeldung im Förderjahr -> Maßnahme im Förderjahr
# nicht mehr gültig; Abmeldung in einem Vorjahr -> ausgestiegen.
deregistration_effective if {
	d := val(participation, "deregistration_date")
	d != null
	not deregistration_after_inspection_notice
}

# O6_5-GEN-EXIT-UNTIL-INSPECTION: Ausstieg nur bis zur Durchführung/Ankündigung einer
# Vor-Ort-Kontrolle bzw. Mitteilung des Ergebnisses einer Verwaltungskontrolle.
deregistration_after_inspection_notice if {
	d := val(participation, "deregistration_date")
	n := val(participation, "inspection_notice_date")
	d != null
	n != null
	parse_date(d) >= parse_date(n)
}

deregistered_for_year if {
	deregistration_effective
	parse_date(participation.deregistration_date) <= date_of(year, "12-31")
}

contract_failures contains "O6_5-EXIT-DEREGISTRATION-TIMING" if deregistered_for_year

# O6_5-GEN-TAKEOVER: Maßnahmenübernahme nur in Einzelfällen (Betriebsauflösung,
# -teilung, -zusammenlegung); Tiere und Flächen vom selben Vorbetrieb.
restricted_takeover_reasons := {r.reason | some r in data.o6_5.restricted_takeover_reasons}

contract_failures contains "O6_5-GEN-TAKEOVER" if {
	participation.takeover.is_takeover == true
	not takeover_ok
}

takeover_ok if {
	participation.takeover.reason in restricted_takeover_reasons
	participation.takeover.animals_and_land_from_same_predecessor == true
}

# O6_5-MIN-PARTICIPATION / O6_5-GEN-ACCESS-NONCOMPLIANCE-NO-CONTRACT
contract_failures contains "O6_5-MIN-PARTICIPATION" if not minimum_participation_met

access_requirements_met if {
	count(applicant_failures) == 0
	count(contract_failures) == 0
}

# O6_5-CON-LAPSE: Vertrag erlischt, wenn die Mindestteilnahme nicht erfüllt ist.
contract_lapses if not minimum_participation_met

# O6_5-CON-AUTO-RENEWAL: automatische Verlängerung um ein Förderjahr ohne Abmeldung.
contract_renews_next_year if {
	access_requirements_met
	not contract_lapses
	not val(participation, "deregistration_date") != null
}

# title: o6_5 – Prämienberechnung
# description: >-
#   Prämiensätze je Tierkategorie und Prämienstufe, Zuschläge für besondere
#   Generhaltungsprogramme und Milchleistungskontrolle, Kürzungsstufen,
#   Betriebsgrößenmodulation und Auszahlungsgrößen.
package oepul.o6_5

# O6_5-PREM-RATES-PERIOD: Antragsjahr 2023 bzw. Prämiensätze ab 01.01.2024.
rate_period := "2023" if {
	year == 2023
} else := "ab_2024"

rate_row(category) := r if {
	some r in data.o6_5.premium_rates
	r.category == category
	r.rate_period == rate_period
}

stage_field := {"A": "stage_a_eur", "B": "stage_b_eur"}

# O6_5-PREM-STAGE-ASSIGNMENT / O6_5-PREM-RATES
base_rate(a) := rate_row(a.animal_category)[stage_field[breed_meta[a.breed].premium_stage]]

# O6_5-PREM-GEP-SURCHARGE: Zuschlag für Rassen mit besonderem Generhaltungsprogramm.
gep_surcharge(a) := rate_row(a.animal_category).gep_surcharge_eur if {
	breed_meta[a.breed].special_gep == true
} else := 0

# O6_5-PREM-MLK-SURCHARGE: Zuschlag für Kühe mit Milchleistungskontrolle.
mlk_surcharge(a) := rate_row(a.animal_category).mlk_surcharge_eur if {
	a.animal_category == "kuh"
	a.milk_recording == true
} else := 0

round2(x) := round(x * 100) / 100

animal_premium(a) := round2((base_rate(a) + gep_surcharge(a)) + mlk_surcharge(a)) if {
	is_number(base_rate(a))
}

# Summe der Prämien aller förderbaren Förderplätze (vor Kürzungen und Modulation).
premium_total_eur := round2(sum([slot_premium(animal_by_id[id]) | some id in eligible_slot_ids]))

# O6_5-GEN-SANCTION-STAGES / O6_5-GEN-SANCTION-2027-RETENTION / O6_5-GEN-EXCLUSION-TWO-100
sanction_stage := object.get(participation, "content_violation_stage", "none")

sanction_stage_row := r if {
	some r in data.o6_5.sanction_stages
	r.stage == sanction_stage
}

excluded_from_measure if {
	object.get(participation, "full_reductions_in_contract_period", 0) >= params.sanction_exclusion_after_full_reductions
}

excluded_from_measure if sanction_stage == "exclusion"

default reduction_percent := 0

reduction_percent := 100 if {
	excluded_from_measure
} else := 0 if {
	sanction_stage == "none"
} else := sanction_stage_row.reduction_percent_from_2027 if {
	year >= params.warning_replaced_by_retention_from_year
} else := sanction_stage_row.reduction_percent

# O6_5-GEN-MODULATION: Betriebsgrößenmodulation nach Gesamtfläche des Betriebes.
total_area_ha := object.get(input, ["land", "total_area_ha"], 0)

bracket_upper(b) := b.upper_ha if {
	b.upper_ha != null
	b.upper_ha < total_area_ha
} else := total_area_ha

modulated_area_ha := sum([x | some b in data.o6_5.modulation_brackets; total_area_ha > b.lower_ha; x := (bracket_upper(b) - b.lower_ha) * b.factor])

modulation_factor := 1 if {
	total_area_ha <= 0
} else := modulated_area_ha / total_area_ha

premium_after_reductions_eur := round2(((premium_total_eur * (100 - reduction_percent)) / 100) * modulation_factor)

# Auszahlungsbetrag für o6_5 (0, wenn Zugangs-/Vertragsvoraussetzungen fehlen).
payout_eur := premium_after_reductions_eur if {
	access_requirements_met
} else := 0

# O6_5-GEN-SMALL-AMOUNT: Auszahlungsbeträge bis 50 Euro können entfallen.
payout_may_be_waived if {
	payout_eur > 0
	payout_eur <= params.small_payout_threshold_eur
}

# O6_5-GEN-PAYMENT-TIMING: Teilzahlung max. 75 %, Auszahlung bis 30.06. des Folgejahres.
max_advance_payment_eur := round2(payout_eur * params.advance_payment_max_share)

payment_deadline := concat("-", [format_int(year + 1, 10), params.payment_deadline_md])

